package com.ems.controller; import com.ems.dao.EmployeeDAO; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException; @WebServlet("/employees/delete") public class DeleteEmployeeServlet extends HttpServlet{protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{try{long id=Long.parseLong(r.getParameter("id"));s.sendRedirect(r.getContextPath()+"/employees?success="+(new EmployeeDAO().delete(id)?"deleted":"missing"));}catch(Exception e){s.sendRedirect(r.getContextPath()+"/employees?error=invalid");}}}
